def check_rule(node):
    if isinstance(node, ast.Expr) and isinstance(node.value, ast.Call) and node.value.func.id == 're' and node.value.args[0].id in ['findall', 'search', 'match', 'finditer']:
        pattern = node.value.args[1].s
        return not re.fullmatch(r'^(?=\b(?<!\w)\w|\w(?!\b\w)\b)\w+\W+\b(?=\b(?!\w)\w|\w(?!\b\w)\b)\w+$', pattern)
